let lastSceneFrame=0,lastSceneKey='';function render(time){window.scopeFrame?.(time);if(document.hidden||time-lastSceneFrame<33){requestAnimationFrame(render);return}const rect=canvas.getBoundingClientRect();if(rect.width<10||rect.height<10||$('modal').open){requestAnimationFrame(render);return}const dpr=Math.min(devicePixelRatio||1,1.5);if(canvas.width!==Math.round(rect.width*dpr)||canvas.height!==Math.round(rect.height*dpr)){canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr)}W=rect.width;H=rect.height;const sceneKey=[W,H,angle,tilt,zoom,selected,mode,tool,exploded,pending?.id,pending?.pin,window.visualRevision||0].join('|');if(!running&&sceneKey===lastSceneKey){requestAnimationFrame(render);return}lastSceneKey=sceneKey;lastSceneFrame=time;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,W,H);scale=Math.min(W/12,H/8)*zoom;hits=[];pinHits=[];if(mode==='schematic'){drawSchematic();requestAnimationFrame(render);return}if(window.showGrid!==false)for(let i=-9;i<=9;i++){line3([i,0,-9],[i,0,9],i===0?'#354257':'#253044');line3([-9,0,i],[9,0,i],i===0?'#354257':'#253044')}
faces=[];box(0,-.2,0,8,.25,5,'#ced3cf');for(let rail of [-2.15,2.15]){line3([-3.7,-.055,rail],[3.7,-.055,rail],'#d06a70',1.5);line3([-3.7,-.055,rail+.13],[3.7,-.055,rail+.13],'#5d8fa5',1.5)}faces.sort((a,b)=>b.d-a.d).forEach(f=>{ctx.beginPath();f.pp.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.fillStyle=f.color;ctx.fill();ctx.strokeStyle='#10182322';ctx.lineWidth=.4;ctx.stroke()});for(let x=-3.5;x<=3.5;x+=.25)for(let z=-1.65;z<=1.65;z+=.25){if(Math.abs(z)<.17)continue;const p=project(x,-.06,z);ctx.fillStyle='#555e63';ctx.beginPath();ctx.ellipse(p.x,p.y,1.1*zoom,.7*zoom,0,0,7);ctx.fill()}
faces=[];nodes.forEach(n=>drawComponent(n,time));faces.sort((a,b)=>b.d-a.d).forEach(f=>{ctx.beginPath();f.pp.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.fillStyle=f.color;ctx.fill();ctx.strokeStyle='#10182322';ctx.lineWidth=.4;ctx.stroke()});
window.drawDetailedParts?.();wires.forEach((w,i)=>{const a=nodes.find(n=>n.id===w[0].id),b=nodes.find(n=>n.id===w[1].id);if(!a||!b)return;const p=pinPos(a,w[0].pin),q=pinPos(b,w[1].pin);const pts=[p,[p[0],1.15,p[2]],[q[0],1.15,q[2]],q].map(p=>project(...p));ctx.beginPath();ctx.moveTo(pts[0].x,pts[0].y);ctx.bezierCurveTo(pts[1].x,pts[1].y,pts[2].x,pts[2].y,pts[3].x,pts[3].y);ctx.strokeStyle=['#eb6e74','#75cdb2','#e5bb6a','#7ea3ec'][i%4];ctx.lineWidth=3*zoom;ctx.stroke();if(running&&lastSim.current>0){const t=(time*.0004+i*.3)%1,mt=1-t;const xx=mt**3*pts[0].x+3*mt**2*t*pts[1].x+3*mt*t*t*pts[2].x+t**3*pts[3].x,yy=mt**3*pts[0].y+3*mt**2*t*pts[1].y+3*mt*t*t*pts[2].y+t**3*pts[3].y;ctx.beginPath();ctx.arc(xx,yy,3,0,7);ctx.fillStyle='#e1ffee';ctx.fill()}});
nodes.forEach(n=>{const c=catalog.find(c=>c.type===n.type),p=project(n.x,.5,n.z);hits.push({id:n.id,x:p.x,y:p.y});if(n.type==='led'&&running&&lastSim.current>0&&lastSim.active?.includes(n.id)){const g=ctx.createRadialGradient(p.x,p.y,0,p.x,p.y,32*zoom);g.addColorStop(0,'#ff5b6655');g.addColorStop(1,'#ff5b6600');ctx.fillStyle=g;ctx.fillRect(p.x-35*zoom,p.y-35*zoom,70*zoom,70*zoom)}if(n.id===selected){ctx.strokeStyle='#64edb5';ctx.lineWidth=1.5;ctx.setLineDash([4,4]);ctx.beginPath();ctx.ellipse(p.x,p.y+15,48*zoom,25*zoom,0,0,7);ctx.stroke();ctx.setLineDash([])}const label=project(n.x,1.5,n.z);ctx.font='11px Heebo,Arial';ctx.textAlign='center';ctx.fillStyle='#101a29dc';ctx.fillRect(label.x-46,label.y-15,92,23);ctx.fillStyle=n.id===selected?'#8af2c5':'#dbe7f7';ctx.fillText(c.name,label.x,label.y);for(let i=0;i<catalog.find(c=>c.type===n.type).pins.length;i++){const p=project(...pinPos(n,i));pinHits.push({id:n.id,pin:i,x:p.x,y:p.y});ctx.beginPath();ctx.arc(p.x,p.y,tool==='wire'?7:4,0,7);ctx.fillStyle=pending?.id===n.id&&pending.pin===i?'#fff':i===0?'#f4b985':'#8bb1e3';ctx.fill();ctx.strokeStyle='#18252e';ctx.stroke();if(tool==='wire'){ctx.fillStyle='#fff';ctx.fillText(c.pins[i],p.x,p.y+20)}}});window.sceneFrameRendered?.(time);requestAnimationFrame(render)}
function drawSchematic(){const pos=n=>({x:W/2+n.x*scale,y:H/2+n.z*scale*.8});for(let x=0;x<W;x+=22)for(let y=0;y<H;y+=22){ctx.fillStyle='#273547';ctx.fillRect(x,y,1,1)}wires.forEach((w,i)=>{const a=nodes.find(n=>n.id===w[0].id),b=nodes.find(n=>n.id===w[1].id);if(!a||!b)return;const p=pos(a),q=pos(b);function offset(p,n,i){const c=catalog.find(c=>c.type===n.type),h=Math.ceil(c.pins.length/2);p.x+=c.pins.length>2?(i<h?-45:45):(i?35:-35);p.y+=c.pins.length>2?(i%h-(h-1)/2)*12:0}offset(p,a,w[0].pin);offset(q,b,w[1].pin);ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo((p.x+q.x)/2,p.y);ctx.lineTo((p.x+q.x)/2,q.y);ctx.lineTo(q.x,q.y);ctx.strokeStyle=['#e47982','#7cd5b4','#dcc178'][i%3];ctx.lineWidth=2;ctx.stroke()});nodes.forEach(n=>{let p=pos(n),c=catalog.find(c=>c.type===n.type);hits.push({...p,id:n.id});ctx.strokeStyle=selected===n.id?'#64edb5':'#b6c8dc';ctx.lineWidth=2;ctx.fillStyle='#172333';ctx.fillRect(p.x-27,p.y-17,54,34);ctx.beginPath();ctx.moveTo(p.x-35,p.y);ctx.lineTo(p.x-18,p.y);ctx.moveTo(p.x+18,p.y);ctx.lineTo(p.x+35,p.y);if(n.type==='resistor'||n.type==='ldr'){ctx.rect(p.x-18,p.y-9,36,18)}else if(n.type==='source'||n.type==='capacitor'){ctx.moveTo(p.x-5,p.y-15);ctx.lineTo(p.x-5,p.y+15);ctx.moveTo(p.x+5,p.y-10);ctx.lineTo(p.x+5,p.y+10)}else if(n.type==='switch'){ctx.moveTo(p.x-18,p.y);ctx.lineTo(p.x+18,p.y-(n.value?0:17))}else if(n.type==='led'){ctx.moveTo(p.x-14,p.y-11);ctx.lineTo(p.x+10,p.y);ctx.lineTo(p.x-14,p.y+11);ctx.closePath();ctx.moveTo(p.x+10,p.y-12);ctx.lineTo(p.x+10,p.y+12)}else ctx.arc(p.x,p.y,14,0,7);ctx.stroke();ctx.font='12px Heebo,Arial';ctx.textAlign='center';ctx.fillStyle='#d1def1';ctx.fillText(c.name,p.x,p.y-30);ctx.fillStyle='#7d92ac';ctx.fillText(n.value+' '+c.unit,p.x,p.y+35);for(let i=0;i<catalog.find(c=>c.type===n.type).pins.length;i++){const cc=catalog.find(c=>c.type===n.type),half=Math.ceil(cc.pins.length/2),x=p.x+(cc.pins.length>2?(i<half?-45:45):(i?35:-35)),py=p.y+(cc.pins.length>2?(i%half-(half-1)/2)*12:0);pinHits.push({id:n.id,pin:i,x,y:py});ctx.beginPath();ctx.arc(x,py,5,0,7);ctx.fillStyle='#81d8b5';ctx.fill()}})}
canvas.onpointerdown=e=>{const r=canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;const pin=pinHits.find(p=>Math.hypot(p.x-x,p.y-y)<13);if(pin&&tool==='wire'){connectPin(pin.id,pin.pin);return}const hit=hits.slice().reverse().find(p=>Math.hypot(p.x-x,p.y-y)<43*zoom);if(hit)select(hit.id);drag={x:e.clientX,y:e.clientY,moved:false,node:tool==='move'&&hit?nodes.find(n=>n.id===hit.id):null};canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(dx)+Math.abs(dy)>2)drag.moved=true;if(drag.node){if(mode==='schematic'){drag.node.x+=dx/scale;drag.node.z+=dy/(scale*.8)}else{const b=dy/(scale*Math.max(.25,Math.cos(tilt)));drag.node.x+=(dx/scale)*Math.cos(angle)+b*Math.sin(angle);drag.node.z+=-(dx/scale)*Math.sin(angle)+b*Math.cos(angle)}drag.node.x=Math.max(-5,Math.min(5,drag.node.x));drag.node.z=Math.max(-4,Math.min(4,drag.node.z))}else if(mode==='3d'&&tool!=='wire'){angle+=dx*.008;tilt=Math.max(-1.2,Math.min(1.5,tilt-dy*.006))}drag.x=e.clientX;drag.y=e.clientY};canvas.onpointerup=()=>drag=null;canvas.onpointercancel=()=>drag=null;canvas.addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(.4,Math.min(2,zoom*Math.exp(-e.deltaY*.001)))},{passive:false});

